package com.farika.soundflow;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import java.time.Duration;import java.lang.reflect.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LeanUi166Test {
 LibraryUi163Test fixture;
 @Before public void setup()throws Exception{fixture=new LibraryUi163Test();fixture.setup();}
 @After public void cleanup(){fixture.cleanup();ResidentChecks.resetForTest();}
 void invoke(MainActivity a,String name,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(a,args);}
 void send(View v,int action,float x,float y){MotionEvent e=MotionEvent.obtain(0,SystemClock.uptimeMillis(),action,x,y,0);v.dispatchTouchEvent(e);e.recycle();}
 @Test public void actualTrackMenuIsVisibleBeforeUp()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=fixture.screen("likes","");try{MainActivity a=ctrl.get();ListView list=(ListView)fixture.field(a,"list");list.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));list.layout(0,0,400,600);send(list,0,40,30);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(351));AlertDialog menu=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(menu);assertTrue(menu.isShowing());assertEquals("Первый трек",org.robolectric.Shadows.shadowOf(menu).getTitle().toString());assertEquals("Сохранить офлайн",menu.getListView().getAdapter().getItem(2));send(list,1,40,30);assertNull(Shadows.shadowOf(a).getNextStartedService());menu.dismiss();}finally{ctrl.destroy();}}
 @Test public void menuUsesSmallOfflineUriIndexInsteadOfDecryptingCollection()throws Exception{Library.Track copy=fixture.copy();ActivityController<LibraryUi163Test.FakeMain> ctrl=fixture.screen("likes","");try{Map<?,?> index=(Map<?,?>)fixture.field(ctrl.get(),"savedUris");assertEquals(copy.uri,index.get("1"));fixture.c.getSharedPreferences("offline_records",0).edit().clear().commit();invoke(ctrl.get(),"trackMenu",new Class<?>[]{Library.Track.class},LibraryUi163Test.song("1","Song"));AlertDialog menu=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals("Удалить из офлайна",menu.getListView().getAdapter().getItem(2));menu.dismiss();}finally{ctrl.destroy();}}
 @Test public void dismissedPlayerDropsAllViewReferences()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=fixture.screen("likes","");try{PlaybackService service=new PlaybackService();service.current="sc:1";PlaybackService.instance=service;invoke(ctrl.get(),"openPlayer",new Class<?>[]{});Dialog player=(Dialog)fixture.field(ctrl.get(),"playerDialog");assertNotNull(player);assertTrue(player.isShowing());player.dismiss();Shadows.shadowOf(Looper.getMainLooper()).idle();for(String field:new String[]{"playerDialog","playerCover","playerFallback","playerTitle","playerArtist","playerPlay","playerTime","playerTotal","playerLike","playerShuffle","playerRepeat","playerSource","progress"})assertNull(field,fixture.field(ctrl.get(),field));}finally{PlaybackService.instance=null;ctrl.destroy();}}
 public static class WarmMain extends LibraryUi163Test.FakeMain {int warms,submits;@Override protected AccountWriter createAccountWriter(AccountWriter.Callback callback){return new AccountWriter(this,callback){public void warm(){warms++;}public boolean submit(String op,String track,String list,String name){submits++;return true;}};}}
 ActivityController<WarmMain> warmScreen()throws Exception{Bundle b=new Bundle();b.putString("process",SoundFlowApplication.PROCESS);b.putString("page","library");b.putString("filter","likes");ActivityController<WarmMain> ctrl=Robolectric.buildActivity(WarmMain.class).create(b);fixture.waitFor(ctrl.get());return ctrl;}
 @Test public void createDialogWarmsOnlyAfterExplicitUserIntent()throws Exception{ActivityController<WarmMain> ctrl=warmScreen();try{assertEquals(0,ctrl.get().warms);invoke(ctrl.get(),"newPlaylist",new Class<?>[]{Library.Track.class},(Object)null);assertEquals(1,ctrl.get().warms);assertEquals(0,ctrl.get().submits);org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().dismiss();}finally{ctrl.destroy();}}
 @Test public void playlistPickerWarmsInParallelButDoesNotWrite()throws Exception{ActivityController<WarmMain> ctrl=warmScreen();try{invoke(ctrl.get(),"choosePlaylist",new Class<?>[]{Library.Track.class},LibraryUi163Test.song("1","Song"));assertEquals(1,ctrl.get().warms);assertEquals(0,ctrl.get().submits);for(int i=0;i<100;i++){Shadows.shadowOf(Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();if(d!=null&&d.isShowing()){d.dismiss();return;}Thread.sleep(10);}fail("Picker did not open");}finally{ctrl.destroy();}}
}
